int process_data_stream(const u_char* data, int len) {
    if (len <= 0 || data == nullptr) {
        return 0;
    }

    int processed = 0;
    u_char buffer[1024];
    int buffer_index = 0;
    u_char last_char = 0;

    for (int i = 0; i < len; ++i) {
        u_char current_char = data[i];
        processed++;

        if (current_char == '\r') {
            if (i + 1 < len && data[i + 1] == '\n') {
                // CRLF sequence, skip both and emit line
                i++;
                if (buffer_index > 0) {
                    // Emit line from buffer
                    buffer_index = 0;
                }
            } else {
                // Standalone CR, emit line if buffer has content
                if (buffer_index > 0) {
                    buffer_index = 0;
                }
            }
        } else if (current_char == '\n') {
            // LF, emit line if buffer has content
            if (buffer_index > 0) {
                buffer_index = 0;
            }
        } else {
            // Regular character, add to buffer
            if (buffer_index < sizeof(buffer) - 1) {
                buffer[buffer_index++] = current_char;
            }
        }

        last_char = current_char;
    }

    // Handle trailing line if needed
    if ((last_char == '\n' || last_char == '\r') && buffer_index > 0) {
        buffer_index = 0;
    }

    return processed;
}
